import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { test } from "node:test";
import { compile, initLowering, loweringReady } from "../src/engine/lowering.ts";
import { EngineError } from "../src/engine/contract.ts";
import type { PlanGraph, PlanNode } from "../src/engine/contract.ts";

// RFC-004: there is ONE browser-dialect lowering, the Rust crate geo-lowering, compiled to WebAssembly and called by the page. These tests
// load that very module from disk and check it against (1) the golden fixtures generated by the Rust reference (the web glue must not
// change a byte) and (2) the semantic rules the old TypeScript compiler used to carry (now defined once, in Rust).
await initLowering(readFileSync(new URL("../src/engine/generated/geo_lowering.wasm", import.meta.url)));

const dir = new URL("../../crates/geo-engine-browser/tests/fixtures/lowering/", import.meta.url);
const fixtures = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();

test("the Rust lowering module is loaded", () => {
  assert.ok(loweringReady());
});

test("there are golden fixtures to compare against", () => {
  assert.ok(fixtures.length >= 11, `found ${fixtures.length}`);
});

for (const f of fixtures) {
  const fx = JSON.parse(readFileSync(new URL(f, dir), "utf8")) as {
    name: string; plan: PlanGraph; sources: Record<string, { covering: string[] | null }>; max_rows: number;
    expected: { sql?: string; files?: string[]; error_kind?: string };
  };
  test(`WebAssembly lowering == golden fixture: ${fx.name}`, () => {
    const bindings = Object.fromEntries(
      Object.entries(fx.sources).map(([uri, s]) => [uri, {
        url: `/api/files/${uri}`, access: "range" as const,
        covering: s.covering ? { xmin: s.covering[0], ymin: s.covering[1], xmax: s.covering[2], ymax: s.covering[3], declared: true } : null,
      }]),
    );
    if (fx.expected.error_kind) {
      assert.throws(() => compile(fx.plan, bindings, fx.max_rows), (e: unknown) => e instanceof EngineError && e.kind === fx.expected.error_kind, fx.name);
      return;
    }
    const out = compile(fx.plan, bindings, fx.max_rows);
    assert.equal(out.sql, fx.expected.sql);
    assert.deepEqual(out.files.map((x) => x.uri), fx.expected.files);
  });
}

// ---- semantic rules (ported from the retired TypeScript compiler's tests; they now exercise the Rust code) ----
const schema = {
  fields: [{ name: "id", data_type: "int64" }, { name: "category", data_type: "utf8" }, { name: "geometry", data_type: { other: "geometry" } }],
  geometry_columns: [{ name: "geometry", geometry_type: "polygon", crs: { epsg: 4326 } }],
};
const bbox = { min_x: 104, min_y: 12, max_x: 105, max_y: 13, crs: { epsg: 4326 } as const };
const cov = { xmin: "bbox.xmin", ymin: "bbox.ymin", xmax: "bbox.xmax", ymax: "bbox.ymax", declared: true };
const src: PlanNode = { op: "source", uri: "a.parquet", format: "geo_parquet", schema };
const sources = { "a.parquet": { url: "/api/files/a", covering: cov } };
const plan = (nodes: Record<string, PlanNode>, root: string): PlanGraph => ({ ir_version: "0.3", nodes, root });

test("bbox filter is the covering-box overlap; count aggregate; one CTE per node; one extra row requested", () => {
  const p = plan({ s: src, f: { op: "bbox_filter", input: "s", geometry_column: "geometry", bbox }, a: { op: "aggregate", input: "f", group_by: [], aggregates: [{ func: "count", column: null, alias: "n" }] } }, "a");
  const { sql, files } = compile(p, sources, 1000);
  assert.match(sql, /read_parquet\('gf_src_0\.parquet'\)/);
  assert.match(sql, /"bbox"\."xmin" <= 105\.0 AND "bbox"\."xmax" >= 104\.0 AND "bbox"\."ymin" <= 13\.0 AND "bbox"\."ymax" >= 12\.0/);
  assert.match(sql, /COUNT\(\*\) AS "n"/);
  assert.match(sql, /LIMIT 1001$/);
  assert.equal(files.length, 1);
  assert.equal(files[0].url, "/api/files/a");
});

test("sorting puts NULLs last in both directions", () => {
  const p = plan({ s: src, o: { op: "sort", input: "s", keys: [{ column: "id", descending: true }, { column: "category", descending: false }] } }, "o");
  assert.match(compile(p, sources, 10).sql, /ORDER BY "id" DESC NULLS LAST, "category" ASC NULLS LAST/);
});

test("a shared source is compiled once", () => {
  const p = plan({ s: src, a: { op: "filter", input: "s", predicate: { kind: "compare", column: "id", op: "le", value: { int: 2 } } }, l: { op: "limit", input: "a", n: 1 } }, "l");
  assert.equal(compile(p, sources, 10).sql.match(/read_parquet\(/g)?.length, 1);
});

test("literals are escaped (no injection through values or identifiers)", () => {
  const p = plan({ s: src, f: { op: "filter", input: "s", predicate: { kind: "compare", column: 'cat"; DROP', op: "eq", value: { str: "x' OR '1'='1" } } } }, "f");
  assert.ok(compile(p, sources, 10).sql.includes(`"cat""; DROP" = 'x'' OR ''1''=''1'`));
});

test("unsupported operations and a missing covering column are refused, not approximated", () => {
  const spatial = plan({ s: src, i: { op: "intersects", input: "s", geometry_column: "geometry", with: { wkt: "POINT(0 0)", crs: { epsg: 4326 } } } }, "i");
  assert.throws(() => compile(spatial, sources, 10), (e: unknown) => e instanceof EngineError && e.kind === "unsupported");
  const noCov = plan({ s: src, f: { op: "bbox_filter", input: "s", geometry_column: "geometry", bbox } }, "f");
  assert.throws(() => compile(noCov, { "a.parquet": { url: "/x", covering: null } }, 10), (e: unknown) => e instanceof EngineError && e.kind === "unsupported");
});

test("structural problems are refused: cycle, missing node, unbound source, unusable number", () => {
  assert.throws(() => compile(plan({ a: { op: "limit", input: "b", n: 1 }, b: { op: "limit", input: "a", n: 1 } }, "a"), sources, 10), /cycle/);
  assert.throws(() => compile(plan({ a: { op: "limit", input: "ghost", n: 1 } }, "a"), sources, 10), /missing node/);
  assert.throws(() => compile(plan({ s: src }, "s"), {}, 10), /not bound/);
  // JSON cannot carry NaN (it becomes null): the request is refused as invalid rather than guessed
  const nan = plan({ s: src, f: { op: "bbox_filter", input: "s", geometry_column: "geometry", bbox: { ...bbox, min_x: Number.NaN } } }, "f");
  assert.throws(() => compile(nan, sources, 10), (e: unknown) => e instanceof EngineError && e.kind === "invalid");
  // a finite number outside the portable literal range is refused by the shared literal rules
  const huge = plan({ s: src, f: { op: "bbox_filter", input: "s", geometry_column: "geometry", bbox: { ...bbox, max_x: 1e30 } } }, "f");
  assert.throws(() => compile(huge, sources, 10), /portable literal range/);
});

test("geometry is converted to WKB at the scan (typed GEOMETRY(crs) cannot be streamed out of DuckDB-Wasm)", () => {
  const { sql } = compile(plan({ s: src, l: { op: "limit", input: "s", n: 5 } }, "l"), sources, 10);
  assert.match(sql, /SELECT \* REPLACE \(ST_AsWKB\("geometry"\) AS "geometry"\) FROM read_parquet\('gf_src_0\.parquet'\)/);
  const noGeom: PlanNode = { op: "source", uri: "a.parquet", format: "geo_parquet", schema: { fields: [], geometry_columns: [] } };
  assert.match(compile(plan({ s: noGeom }, "s"), sources, 10).sql, /SELECT \* FROM read_parquet\('gf_src_0\.parquet'\)/);
});
